export function data(o,keys){if(!o||typeof o!=='object'||![Object.prototype,null].includes(Object.getPrototypeOf(o))||Reflect.ownKeys(o).length!==keys.length)throw Error('FARM_CONTACT_DATA');const r={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))throw Error('FARM_CONTACT_DATA');r[k]=d.value}return r}
export function foot(o){if(!Array.isArray(o)||Object.getPrototypeOf(o)!==Array.prototype||Reflect.ownKeys(o).length!==3||Object.getOwnPropertyDescriptor(o,'length')?.value!==2)throw Error('FARM_CONTACT_FOOT');return ['0','1'].map(k=>{const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value')||!Number.isSafeInteger(d.value))throw Error('FARM_CONTACT_FOOT');return d.value})}
export function context(read){const c=data(read(),['world','record','epoch','signal','pose','clock','appearance']);if(!['boy','girl'].includes(c.appearance)||!c.world||typeof c.world!=='object'||!c.record||typeof c.record!=='object'||!Number.isSafeInteger(c.epoch)||c.epoch<0||!(c.signal instanceof AbortSignal)||c.signal.aborted)throw Error('FARM_CONTACT_OWNER');const p=data(c.pose,['mapId','revision','state','imageSHA','maskSHA','foot','facing','phase']);p.foot=foot(p.foot);const k=data(c.clock,['ms','minutes']);if(!Number.isFinite(k.ms)||k.ms<0||!Number.isFinite(k.minutes)||k.minutes<0||k.minutes>=1440||p.phase!=='field')throw Error('FARM_CONTACT_CLOCK_PHASE');return {...c,pose:p,clock:k}}
export const sameLineage=(a,b)=>a.world===b.world&&a.record===b.record&&a.epoch===b.epoch&&a.signal===b.signal&&JSON.stringify(a.pose)===JSON.stringify(b.pose)&&a.appearance===b.appearance;
export const same=(a,b)=>sameLineage(a,b)&&JSON.stringify(a.clock)===JSON.stringify(b.clock);
